package glitch

import data.glitch_lib

bucket_type_keywords := {"s3", "bucket", "storage", "cors"}
cors_attr_names := {"allowed_origins", "allowed_methods", "allowed_headers"}

is_bucket_resource(node) {
    glitch_lib.contains(node.type, bucket_type_keywords[_])
}

is_wildcard(value) {
    value.ir_type == "String"
    value.value == "*"
}

has_wildcard_in_array(value) {
    value.ir_type == "Array"
    item := value.value[_]
    item.ir_type == "String"
    item.value == "*"
}

has_delete_in_array(value) {
    value.ir_type == "Array"
    item := value.value[_]
    item.ir_type == "String"
    lower(item.value) == "delete"
}

is_insecure_cors_attr(attr) {
    attr.name == "allowed_origins"
    is_wildcard(attr.value)
}

is_insecure_cors_attr(attr) {
    attr.name == "allowed_origins"
    has_wildcard_in_array(attr.value)
}

is_insecure_cors_attr(attr) {
    attr.name == "allowed_methods"
    is_wildcard(attr.value)
}

is_insecure_cors_attr(attr) {
    attr.name == "allowed_methods"
    has_wildcard_in_array(attr.value)
}

is_insecure_cors_attr(attr) {
    attr.name == "allowed_methods"
    has_delete_in_array(attr.value)
}

is_insecure_cors_attr(attr) {
    attr.name == "allowed_headers"
    is_wildcard(attr.value)
}

is_insecure_cors_attr(attr) {
    attr.name == "allowed_headers"
    has_wildcard_in_array(attr.value)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    is_bucket_resource(node)

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]
    attr.name == cors_attr_names[_]
    is_insecure_cors_attr(attr)

    result := {
        "type": "sec_s3_unsecured_cors",
        "element": attr,
        "path": parent.path,
        "description": "S3 Bucket with Unsecured CORS Policy - Overly permissive CORS configuration allows unrestricted cross-origin access, risking data exposure and CSRF attacks. (CWE-942)"
    }
}

