package glitch

import data.glitch_lib

has_wildcard(value) {
    value.ir_type == "Array"
    item := value.value[_]
    item.ir_type == "String"
    item.value == "*"
}

has_wildcard(value) {
    value.ir_type == "String"
    value.value == "*"
}

has_delete(value) {
    value.ir_type == "Array"
    item := value.value[_]
    item.ir_type == "String"
    lower(item.value) == "delete"
}

is_insecure_cors_attr(name, value) {
    name == "allowed_origins"
    has_wildcard(value)
}

is_insecure_cors_attr(name, value) {
    name == "allowed_methods"
    has_wildcard(value)
}

is_insecure_cors_attr(name, value) {
    name == "allowed_methods"
    has_delete(value)
}

is_insecure_cors_attr(name, value) {
    name == "allowed_headers"
    has_wildcard(value)
}

cors_block_is_insecure(cors_block) {
    attr := cors_block.attributes[_]
    is_insecure_cors_attr(attr.name, attr.value)
}

ansible_node_is_insecure(node) {
    attr := node.attributes[_]
    attr.value.ir_type == "Array"
    hash := attr.value.value[_]
    hash.ir_type == "Hash"
    entry := hash.value[_]
    entry.key.ir_type == "String"
    is_insecure_cors_attr(entry.key.value, entry.value)
}

Glitch_Analysis[result] {
    walk(input, [_, file_block])
    file_block.ir_type == "UnitBlock"
    file_block.path != ""

    walk(file_block, [_, node])
    node.ir_type == "AtomicUnit"

    cors_block := node.statements[_]
    cors_block.ir_type == "UnitBlock"
    cors_block.type == "block"
    glitch_lib.contains(cors_block.name, "cors")

    cors_block_is_insecure(cors_block)

    result := {
        "type": "sec_s3_unsecured_cors",
        "element": cors_block,
        "path": file_block.path,
        "description": "S3 Bucket with Unsecured CORS Policy - Overly permissive CORS configuration allows unrestricted cross-origin access, risking data exposure and CSRF attacks. (CWE-942)"
    }
}

